const min = Number(global.get("setMin") ?? 30);

const marstekPwr = Number(global.get("marstek_power")) || 800;

// Modbus settings
const unitid = 1;
const fc = 6;              // Write Single Holding Register
const quantity = 1;

const ENABLE = 21930;
const DISABLE = 21947;

// Delays (ms)
const delayMode = 900;
const delayTarget = 1800;
const delayPowerDischarge = 2200;
const delayMaxDischarge = 2600;
const delayPowerCharge = 3000;
const delayMaxCharge = 3400;
const delayDisable = 3800;

//------------------------------------------------------------
// Helper: Build Flex Write message
//------------------------------------------------------------
function buildWrite(address, value, topic) {
    return {
        topic: topic,
        payload: {
            value: value,
            fc: fc,
            unitid: unitid,
            address: address,
            quantity: quantity
        }
    };
}

//------------------------------------------------------------
// Helper: Send delayed Modbus message (Output 1)
//------------------------------------------------------------
function sendWrite(address, value, topic, delay) {
    setTimeout(() => {
        node.send([
            buildWrite(address, value, topic),
            null
        ]);
    }, delay);
}

//------------------------------------------------------------
// Helper: Send Target SOC immediately (Output 2)
//------------------------------------------------------------
function sendTargetSOC(value) {
    node.send([
        null,
        {
            topic: "target_soc",
            payload: value
        }
    ]);
}

//------------------------------------------------------------
// Validate mode
//------------------------------------------------------------
if (![0,1,2,3].includes(mode)) {
    node.status({
        fill:"red",
        shape:"ring",
        text:`Unknown mode ${mode}`
    });
    return null;
}

//------------------------------------------------------------
// MODE 0 = NONE
//------------------------------------------------------------
if (mode === 0) {

    node.status({
        fill:"grey",
        shape:"ring",
        text:"None"
    });

    sendTargetSOC(0);

    sendWrite(42000, ENABLE, "rs485-enable", 0);

    sendWrite(42010, 0, "force-none", delayMode);

    sendWrite(42000, DISABLE, "rs485-disable", delayDisable);

    return null;
}

//------------------------------------------------------------
// Determine target
//------------------------------------------------------------
let target;
let label;
let statusColor;
let forceModePayload;

if (mode === 1) {

    target = max;
    label = "Charge";
    statusColor = "green";
    forceModePayload = 1;

}
else if (mode === 2) {

    target = min;
    label = "Discharge";
    statusColor = "yellow";
    forceModePayload = 2;

}
else {

    target = min;
    label = "AntiFeed";
    statusColor = "blue";
    forceModePayload = null;

}

//------------------------------------------------------------
// Status
//------------------------------------------------------------
node.status({
    fill: statusColor,
    shape: "dot",
    text: `${label} Target ${target}%`
});

//------------------------------------------------------------
// Send Target SOC immediately (Output 2)
//------------------------------------------------------------
sendTargetSOC(target);

//------------------------------------------------------------
// Sequence
//------------------------------------------------------------

// Enable RS485
sendWrite(42000, ENABLE, "rs485-enable", 0);

// Force Mode
sendWrite(42010, forceModePayload, "force-mode", delayMode);

// Target SOC
sendWrite(42011, target, "target-soc", delayTarget);

//------------------------------------------------------------
// Charge
//------------------------------------------------------------
if (mode === 1) {

    sendWrite(
        42020,
        marstekPwr,
        "charge-power",
        delayPowerCharge
    );

    sendWrite(
        44002,
        marstekPwr,
        "max-charge-power",
        delayMaxCharge
    );

}

//------------------------------------------------------------
// Discharge
//------------------------------------------------------------
if (mode === 2) {

    sendWrite(
        42021,
        marstekPwr,
        "discharge-power",
        delayPowerDischarge
    );

    sendWrite(
        44003,
        marstekPwr,
        "max-discharge-power",
        delayMaxDischarge
    );

}

return null;

