function addHistory(history, value) {

    const numberValue = Number(value);

    if (isNaN(numberValue)) {
        return history;
    }

    const now = Date.now();

    history.push({

        timestamp: now,

        time: new Date(now).toLocaleTimeString("nl-NL", {
            hour: "2-digit",
            minute: "2-digit"
        }),

        value: numberValue

    });

    return history;
}


function cleanHistory(history) {

    const cutoff =
        Date.now() - HISTORY_TIME;

    history =
        history.filter(item => {

            return (
                item &&
                typeof item.timestamp === "number" &&
                item.timestamp >= cutoff
            );

        });

    if (history.length > MAX_HISTORY) {

        history =
            history.slice(
                -MAX_HISTORY
            );

    }

    return history;
}


