let data = global.get("ZonneplanTijdsloten");

if (!data || !Array.isArray(data.data)) {
    node.status({
        fill: "red",
        shape: "ring",
        text: "Geen Zonneplan data"
    });
    return null;
}

let prices = data.data.map((slot, index) => {
    return {
        index: index,
        price: Number(slot.prijsZP)
    };
});

let now = new Date();

let hour = now.getHours();
let quarter = Math.floor(now.getMinutes() / 15);
let currentIndex = hour * 4 + quarter;

let currentPrice = prices[currentIndex]?.price;

node.status({
    fill: "green",
    shape: "ring",
    text: "Current Price: " + currentPrice
});

msg.topic = "ZonneplanPrices";

msg.payload = {
    title: "Price",
    prices: prices,
    currentIndex: currentIndex,
    currentPrice: currentPrice
};

return msg;
